#ifndef ROOM_H
#define ROOM_H

// A single-screen hacking room (plan.md 8a): solid tiles, terminals to hack, a gate, foes.
// Data comes from assets/rooms.h (generated by tools/build_rooms.py). State is private to room.c.

// Draw the room of era id (0-3) and place Geeko; the hack time follows the era. Turns rendering off;
// the caller turns it back on.
void room_load(unsigned char id);

// One frame, after hero_update(): terminals (hold B next to one), foes, contact, the gate.
void room_update(unsigned char pad);

// 1 if the solid tile at pixel (x, y) blocks Geeko. Outside the screen: not solid.
unsigned char room_solid(unsigned char x, unsigned char y);

unsigned char room_hacking(void);    // Geeko is holding B in a terminal's zone (D-pad ignored)
unsigned char room_hacked(void);
unsigned char room_total(void);
unsigned char room_done(void);       // Geeko reached the open gate
unsigned char room_clean(void);      // not hit once so far

void room_draw_foes(void);

#endif // ROOM_H
